INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('119', '19', '3', '3', 'proof', '14', '设 \(f\) 在 \([0,1]\) 连续，且 \(1\le f(x)\le3\)。证明
\[1\le\int_0^1f(x)\,dx\int_0^1\frac{dx}{f(x)}\le\frac43.\]', '所给双边不等式成立。', '下界由 Cauchy 不等式。上界利用 \((f-1)(3-f)\ge0\)，即 \(f+3/f\le4\)，积分后结合算术—几何平均不等式即得。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0,1] ) 连续，且 (1 f(x) 3 )。证明 [1 0 1f(x) ,dx 0 1 dx f(x) 43. ] 所给双边不等式成立。 下界由 Cauchy 不等式。上界利用 ((f-1)(3-f) 0 )，即 (f+3/f 4 )，积分后结合算术—几何平均不等式即得。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('120', '19', '4', '4', 'calculation', '12', '计算 \(\iiint_V(x^2+y^2)\,dV\)，其中 \(V\) 由
\[x^2+y^2+(z-2)^2\ge4,\quad x^2+y^2+(z-1)^2\le9,\quad z\ge0\]
所围成。', '\(\displaystyle\frac{256\pi}{3}\)。', '用柱坐标，按两个球面的交圈分段确定 \(r,z\) 的范围；对 \(r^2\cdot r\,dr\,d\theta\,dz\) 积分，得 \(256\pi/3\)。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 计算 ( V(x 2+y 2) ,dV )，其中 (V ) 由 [x 2+y 2+(z-2) 2 4, x 2+y 2+(z-1) 2 9, z 0 ] 所围成。 ( 256 3 )。 用柱坐标，按两个球面的交圈分段确定 (r,z ) 的范围；对 (r 2 r ,dr ,d ,dz ) 积分，得 (256 /3 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('121', '19', '5', '5', 'proof', '14', '设 \(f(x,y)\) 在区域 \(D\) 内可微，且 \(\sqrt{f_x^2+f_y^2}\le M\)。若线段 \(AB\subset D\)，证明
\[|f(A)-f(B)|\le M|AB|.\]', '所给 Lipschitz 估计成立。', '参数化线段 \(X(t)=A+t(B-A)\)。对 \(f(X(t))\) 用一元中值定理，再由 Cauchy 不等式估计方向导数不超过 \(M|AB|\)。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 设 (f(x,y) ) 在区域 (D ) 内可微，且 ( f x 2+f y 2 M )。若线段 (AB D )，证明 [|f(A)-f(B)| M|AB|. ] 所给 Lipschitz 估计成立。 参数化线段 (X(t)=A+t(B-A) )。对 (f(X(t)) ) 用一元中值定理，再由 Cauchy 不等式估计方向导数不超过 (M|AB| )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('122', '19', '6', '6', 'proof', '14', '证明对连续函数 \(f(x)>0\)，有
\[\ln\int_0^1f(x)\,dx\ge\int_0^1\ln f(x)\,dx.\]', '所给 Jensen 不等式成立。', '函数 \(\ln x\) 为凹函数。对积分作等分 Riemann 和并应用有限形式 Jensen 不等式，再令分点数趋于无穷。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 证明对连续函数 (f(x)>0 )，有 [ 0 1f(x) ,dx 0 1 f(x) ,dx. ] 所给 Jensen 不等式成立。 函数 ( x ) 为凹函数。对积分作等分 Riemann 和并应用有限形式 Jensen 不等式，再令分点数趋于无穷。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('123', '19', '7', '7', 'proof', '14', '已知正数列 \(\{a_k\},\{b_k\}\) 满足 \(b_{k+1}-b_k\ge\delta>0\)。证明：若 \(\sum_{k=1}^\infty a_k\) 收敛，则
\[\sum_{k=1}^\infty\frac{\sqrt[k]{(a_1a_2\cdots a_k)(b_1b_2\cdots b_k)}}{b_{k+1}b_k}\]
收敛。', '所给正项级数收敛。', '令 \(S_k=\sum_{i=1}^ka_ib_i\)。对 \(\sum a_k\) 作 Abel 变换，并用 \(b_{k+1}-b_k\ge\delta\)，可得 \(\sum S_k/(b_kb_{k+1})\) 收敛。又由算术—几何平均不等式，\(\sqrt[k]{\prod_{i=1}^ka_ib_i}\le S_k/k\le S_k\)，比较即得。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 已知正数列 ( a k , b k ) 满足 (b k+1 -b k >0 )。证明：若 ( k=1 a k ) 收敛，则 [ k=1 [k] (a 1a 2 a k)(b 1b 2 b k) b k+1 b k ] 收敛。 所给正项级数收敛。 令 (S k= i=1 ka ib i )。对 ( a k ) 作 Abel 变换，并用 (b k+1 -b k )，可得 ( S k/(b kb k+1 ) ) 收敛。又由算术—几何平均不等式， ( [k] i=1 ka ib i S k/k S k )，比较即得。', '1', 'published') ON CONFLICT (id) DO NOTHING;